/**
 * Audit-chain anchor (`audit-chain-anchor` v1) — tests.
 *
 * The hashes come from the production `AuditChainService` (no mocked algorithm) and the signature
 * uses a real SM2 key generated by the host openssl, so the green/red pair exercises the same path
 * the operator does.
 *
 * 审计链日锚（`audit-chain-anchor` v1）测试。哈希由生产 `AuditChainService` 现算（不 mock 算法），
 * 签名用宿主 openssl 生成的 SM2 私钥，绿/红两向跑的就是运维脚本走的那条路。
 */
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { ConfigService } from '@nestjs/config';
import { AuditChainService } from '../../common/audit-chain/audit-chain.service';
import {
  buildChainAnchor,
  tailsFromRows,
  verifyChainAnchor,
  verifyChainAnchorAgainst,
} from './chain-anchor';

const DATE = '2026-09-18';
const OBSERVED_AT = `${DATE}T00:05:00.000Z`;

const svc = new AuditChainService({
  get: (k: string) =>
    ({ ENCRYPTION_KEY: '0123456789abcdef0123456789abcdef' } as Record<string, string>)[k] ?? null,
} as unknown as ConfigService);

const aiPayloads = [{ action: 'chat', userId: '1' }, { action: 'tool_call', userId: '1' }, { action: 'chat', userId: '2' }];
const aiH1 = svc.computeHash(null, aiPayloads[0]);
const aiH2 = svc.computeHash(aiH1, aiPayloads[1]);
const aiH3 = svc.computeHash(aiH2, aiPayloads[2]);
const aiRows = [
  { id: 1, hash: aiH1 },
  { id: 2, hash: aiH2 },
  { id: 3, hash: aiH3 },
];

const opPayloads = [{ action: 'create', userId: '1' }, { action: 'update', userId: '1' }];
const opH1 = svc.computeHash(null, opPayloads[0]);
const opH2 = svc.computeHash(opH1, opPayloads[1]);
const opRows = [
  { id: 1, hash: opH1 },
  { id: 2, hash: opH2 },
];

function opensslUsable(): boolean {
  try {
    return /^OpenSSL (1\.1\.1|3|[4-9])/.test(
      execFileSync('openssl', ['version'], { stdio: ['ignore', 'pipe', 'ignore'] }).toString(),
    );
  } catch {
    return false;
  }
}
const HAS_OPENSSL = opensslUsable();

describe('链尾推导与产出护栏（无需 openssl）', () => {
  it('tailsFromRows：只数已入链的行，取 id 最大的那条；空链为 null', () => {
    expect(tailsFromRows([])).toBeNull();
    expect(tailsFromRows([{ id: 1, hash: null }, { id: 3, hash: aiH3 }, { id: 2, hash: aiH2 }])).toEqual({
      rows: 2,
      lastId: 3,
      lastHash: aiH3,
    });
  });

  it('无 SM2 私钥拒产', () => {
    expect(() =>
      buildChainAnchor({
        date: DATE,
        observedAt: OBSERVED_AT,
        chains: { aiAudit: tailsFromRows(aiRows), operationAudit: tailsFromRows(opRows) },
        sm2: null,
      }),
    ).toThrow(/SM2 私钥/);
  });

  it('date 与 observedAt 的 UTC 日期不一致 → 拒产', () => {
    expect(() =>
      buildChainAnchor({
        date: DATE,
        observedAt: '2026-09-19T00:05:00.000Z',
        chains: { aiAudit: tailsFromRows(aiRows), operationAudit: tailsFromRows(opRows) },
        sm2: { privateKeyPem: 'x', userId: 'u' },
      }),
    ).toThrow(/不一致/);
  });
});

const describeIfOpenssl = HAS_OPENSSL ? describe : describe.skip;

describeIfOpenssl('链锚产出 / 自校验 / 当前链对照（需 openssl）', () => {
  let dir: string;
  let priv: string;

  beforeAll(() => {
    dir = mkdtempSync(join(tmpdir(), 'chain-anchor-spec-'));
    const privPath = join(dir, 'k.pem');
    execFileSync('openssl', ['genpkey', '-algorithm', 'SM2', '-out', privPath]);
    priv = readFileSync(privPath, 'utf8');
  });
  afterAll(() => rmSync(dir, { recursive: true, force: true }));

  const cfg = () => ({ privateKeyPem: priv, keyId: 'k-1', userId: '1234567812345678' });

  const anchorFor = (
    ai: readonly { id: number; hash?: string | null }[] = aiRows,
    op: readonly { id: number; hash?: string | null }[] = opRows,
  ) =>
    buildChainAnchor({
      date: DATE,
      observedAt: OBSERVED_AT,
      chains: { aiAudit: tailsFromRows(ai), operationAudit: tailsFromRows(op) },
      publishedAt: '2026-09-18T00:06:00.000Z',
      sm2: cfg(),
    });

  it('绿：完整链 A→B→C + 锚 ⇒ 自校验与当前链对照都干净', () => {
    const anchor = anchorFor();
    expect(anchor.chains.aiAudit).toEqual({ rows: 3, lastId: 3, lastHash: aiH3 });
    expect(verifyChainAnchor(anchor)).toEqual({ ok: true, reasons: [] });

    const cmp = verifyChainAnchorAgainst(anchor, { aiAudit: aiRows, operationAudit: opRows });
    expect(cmp.ok).toBe(true);
    expect(cmp.chains.aiAudit.status).toBe('ok');
    expect(cmp.chains.operationAudit.status).toBe('ok');
    expect(cmp.reasons).toEqual([]);
  });

  it('红：链截成 A→B（C 被删）而锚不变 ⇒ 锚自身仍 PASS，对照检出尾部缺失', () => {
    const anchor = anchorFor();
    // Anchor self-verification still passes — it proves the record was not changed.
    // 锚自身仍 PASS —— 它只证明记录未被改。
    expect(verifyChainAnchor(anchor).ok).toBe(true);

    const cmp = verifyChainAnchorAgainst(anchor, { aiAudit: aiRows.slice(0, 2), operationAudit: opRows });
    expect(cmp.ok).toBe(false);
    expect(cmp.chains.aiAudit.status).toBe('tail-missing');
    expect(cmp.chains.aiAudit.reasons.join('')).toMatch(/尾部缺失 1 行/);
    expect(cmp.chains.operationAudit.ok).toBe(true);
  });

  it('同长替换：行数相同但末行被换 ⇒ tail-replaced / last-row-changed', () => {
    // Anchor on A→B, current has B and a new C: the anchored last row (B) survives, the max id moves.
    // 锚在 A→B；当前是 B 与一条新 C：锚定末行 B 还在，但最大 id 变了。
    const anchor = anchorFor(aiRows.slice(0, 2));
    const replaced = [aiRows[1], { id: 4, hash: aiH3 }];
    const cmp = verifyChainAnchorAgainst(anchor, { aiAudit: replaced, operationAudit: opRows });
    expect(cmp.ok).toBe(false);
    expect(cmp.chains.aiAudit.status).toBe('tail-replaced');
    expect(cmp.chains.aiAudit.reasons.join('')).toMatch(/尾部被替换/);
  });

  it('末行 hash 被改 ⇒ last-row-changed', () => {
    const anchor = anchorFor();
    const changed = [{ id: 1, hash: aiH1 }, { id: 2, hash: aiH2 }, { id: 3, hash: 'd'.repeat(64) }];
    const cmp = verifyChainAnchorAgainst(anchor, { aiAudit: changed, operationAudit: opRows });
    expect(cmp.ok).toBe(false);
    expect(cmp.chains.aiAudit.status).toBe('last-row-changed');
    expect(cmp.chains.aiAudit.reasons.join('')).toMatch(/末行被改/);
  });

  it('锚后新增：多出行不是尾部删除；但锚定末行被删仍必报', () => {
    const anchor = anchorFor();
    const h4 = svc.computeHash(aiH3, { action: 'chat', userId: '3' });
    const grown = [...aiRows, { id: 4, hash: h4 }];
    const grew = verifyChainAnchorAgainst(anchor, { aiAudit: grown, operationAudit: opRows });
    expect(grew.ok).toBe(true);
    expect(grew.chains.aiAudit.status).toBe('grew');
    expect(grew.chains.aiAudit.reasons.join('')).toMatch(/锚后新增 1 行/);

    // C (id=3) removed, then D/E added: rows grew, but the anchored tail is gone.
    // 删掉 C（id=3）后再加 D/E：行数变多，但锚定末行没了 —— 不能因「增长」而放过。
    const h5 = svc.computeHash(h4, { action: 'chat', userId: '4' });
    const deletedThenGrew = [aiRows[0], aiRows[1], { id: 4, hash: h4 }, { id: 5, hash: h5 }];
    const cmp = verifyChainAnchorAgainst(anchor, { aiAudit: deletedThenGrew, operationAudit: opRows });
    expect(cmp.ok).toBe(false);
    expect(cmp.chains.aiAudit.status).toBe('last-row-changed');
    expect(cmp.chains.aiAudit.reasons.join('')).toMatch(/末行被删/);
  });

  it('空链：锚记 null，当前仍空 ⇒ empty；当前有行 ⇒ grew（不是删除）', () => {
    const anchor = anchorFor([], []);
    expect(verifyChainAnchor(anchor).ok).toBe(true);
    const empty = verifyChainAnchorAgainst(anchor, { aiAudit: [], operationAudit: [] });
    expect(empty.ok).toBe(true);
    expect(empty.chains.aiAudit.status).toBe('empty');

    const later = verifyChainAnchorAgainst(anchor, { aiAudit: aiRows, operationAudit: opRows });
    expect(later.ok).toBe(true);
    expect(later.chains.aiAudit.status).toBe('grew');
  });

  it('改锚内 chains → rootDigest 复现失败 / 验签失败', () => {
    const anchor = anchorFor();
    const tampered = {
      ...anchor,
      chains: { ...anchor.chains, aiAudit: { ...anchor.chains.aiAudit!, lastHash: 'd'.repeat(64) } },
    };
    const r = verifyChainAnchor(tampered);
    expect(r.ok).toBe(false);
    expect(r.reasons.join('')).toMatch(/rootDigest 与载荷不符|SM2 验签不通过/);
  });

  it('改 observedAt（签名覆盖它）⇒ 自校验失败', () => {
    const anchor = anchorFor();
    const tampered = { ...anchor, observedAt: `${DATE}T00:05:01.000Z` };
    const r = verifyChainAnchor(tampered);
    expect(r.ok).toBe(false);
    expect(r.reasons.join('')).toMatch(/rootDigest 与载荷不符|SM2 验签不通过/);
  });
});
